-- Tier 2 city batch seed: Hamburg, Cologne, Marseille, Wroclaw, Prague, Budapest, Rio de Janeiro, Belo Horizonte
-- Additive and re-runnable. Apply manually in Supabase SQL Editor.
-- Coordinates and place names were source-checked against OpenStreetMap Nominatim before writing this seed.

insert into public.city_packs (slug, name, route_note, finish_label, safety_note, is_active)
values
  ('hamburg', 'Hamburg', 'Harbor districts, Elbe crossings, and northern metro towns across the Hamburg region.', 'Hamburg Tier 2 sheet complete.', 'Ride inside local laws, use public streets and cycle routes, and keep every checkpoint safe.', true),
  ('cologne', 'Cologne', 'Rhine bridges, inner neighborhoods, and regional cities across the Cologne-Bonn corridor.', 'Cologne Tier 2 sheet complete.', 'Ride inside local laws, stay predictable near tram and bridge traffic, and use public approaches.', true),
  ('marseille', 'Marseille', 'Port districts, coastal roads, and outer Provence towns around Marseille.', 'Marseille Tier 2 sheet complete.', 'Ride inside local laws, watch climbs and traffic, and keep checkpoints public.', true),
  ('wroclaw', 'Wroclaw', 'Central islands, park edges, and Lower Silesian towns around Wroclaw.', 'Wroclaw Tier 2 sheet complete.', 'Ride inside local laws, stay alert near tram corridors, and use public checkpoints.', true),
  ('prague', 'Prague', 'River districts, hill edges, and Central Bohemian towns around Prague.', 'Prague Tier 2 sheet complete.', 'Ride inside local laws, respect pedestrian zones, and keep every stop public.', true),
  ('budapest', 'Budapest', 'Danube districts, island crossings, and outer Pest County towns around Budapest.', 'Budapest Tier 2 sheet complete.', 'Ride inside local laws, use public routes, and stay predictable around traffic.', true),
  ('riodejaneiro', 'Rio de Janeiro', 'Beach districts, north-zone corridors, and metro cities around Rio de Janeiro.', 'Rio de Janeiro Tier 2 sheet complete.', 'Ride inside local laws, use safe public approaches, and avoid unsafe roads or restricted areas.', true),
  ('belohorizonte', 'Belo Horizonte', 'Central neighborhoods, Pampulha edges, and metro cities around Belo Horizonte.', 'Belo Horizonte Tier 2 sheet complete.', 'Ride inside local laws, watch hills and traffic, and keep checkpoints public.', true)
on conflict (slug) do update
set
  name = excluded.name,
  route_note = excluded.route_note,
  finish_label = excluded.finish_label,
  safety_note = excluded.safety_note,
  is_active = excluded.is_active,
  updated_at = now();

with pack_refs as (
  select id, slug from public.city_packs where slug in ('hamburg', 'cologne', 'marseille', 'wroclaw', 'prague', 'budapest', 'riodejaneiro', 'belohorizonte')
)
insert into public.city_checkpoints (
  pack_id,
  slug,
  name,
  lat,
  lng,
  district,
  category,
  vibe,
  hint,
  task_local,
  task_fast,
  task_chaotic,
  sort_weight,
  is_active
)
